SELECT country, CASE WHEN rating >= 3.8 THEN 'PREMIUM' ELSE 'STANDARD' END AS rating_tier, COUNT_IF(city = 'Tokyo') AS tokyo_events, SUM(CASE WHEN country = 'US' THEN rating ELSE 0 END) AS us_rating, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN country = 'JP' THEN 1 END), 0), 2) AS rating_per_jp FROM suppliers GROUP BY ROLLUP (country, CASE WHEN rating >= 3.8 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY us_rating;
